sp_widget.client_script:
api.controller = function() {

    var c = this;

    function percent(value, total) {
        if (!total || total <= 0)
            return 0;

        return (value / total) * 100;
    }


    function buildLeaveDonut() {

        var a = c.data.leaveAnalytics || {};

        var total = a.total || 0;

        if (total === 0) {
            c.leaveDonutStyle =
                "conic-gradient(#e5e7eb 0% 100%)";
            return;
        }


        var approved =
            percent(a.approved || 0, total);

        var pendingHod =
            percent(a.pendingHod || 0, total);

        var pendingHr =
            percent(a.pendingHr || 0, total);

        var rejected =
            percent(a.rejected || 0, total);

        var cancelled =
            percent(a.cancelled || 0, total);


        var p1 = approved;

        var p2 = p1 + pendingHod;

        var p3 = p2 + pendingHr;

        var p4 = p3 + rejected;

        var p5 = p4 + cancelled;


        c.leaveDonutStyle =
            "conic-gradient(" +

            "#34c38f 0% " + p1 + "%," +

            "#f59e0b " + p1 + "% " + p2 + "%," +

            "#3b82f6 " + p2 + "% " + p3 + "%," +

            "#ef4444 " + p3 + "% " + p4 + "%," +

            "#8b5cf6 " + p4 + "% " + p5 + "%" +

            ")";
    }


    function buildHrDonut() {

        var a = c.data.hrCaseAnalytics || {};

        var total = a.total || 0;

        if (total === 0) {
            c.hrDonutStyle =
                "conic-gradient(#e5e7eb 0% 100%)";
            return;
        }


        var open =
            percent(a.open || 0, total);

        var inProgress =
            percent(a.inProgress || 0, total);

        var resolved =
            percent(a.resolved || 0, total);

        var closed =
            percent(a.closed || 0, total);


        var p1 = open;

        var p2 = p1 + inProgress;

        var p3 = p2 + resolved;

        var p4 = p3 + closed;


        c.hrDonutStyle =
            "conic-gradient(" +

            "#f59e0b 0% " + p1 + "%," +

            "#3b82f6 " + p1 + "% " + p2 + "%," +

            "#34c38f " + p2 + "% " + p3 + "%," +

            "#6b7280 " + p3 + "% " + p4 + "%" +

            ")";
    }


    buildLeaveDonut();
    buildHrDonut();

};

sp_widget.css:
.uhr-dashboard {
  display: flex;
  width: 100%;
  min-height: 100vh;
  background: #f7f9fc;
  font-family: Arial, sans-serif;
  color: #0f1b45;
}

.uhr-main {
  flex: 1;
  min-width: 0;
  padding: 28px;
}

/* SIDEBAR */

.sn-sidebar {
  width: 255px;
  min-width: 255px;
  min-height: 100vh;
  background: #062f3d;
  color: #ffffff;
  padding: 18px 14px;
  display: flex;
  flex-direction: column;
  box-shadow: 2px 0 8px rgba(0,0,0,.08);
}

.sn-brand {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 4px 10px 18px;
  border-bottom: 1px solid rgba(255,255,255,.12);
  margin-bottom: 16px;
}

.sn-logo-mark {
  width: 36px;
  height: 36px;
  border-radius: 8px;
  background: #81d742;
  color: #052e3a;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
}

.sn-brand-title {
  font-size: 17px;
  font-weight: 700;
}

.sn-brand-sub {
  font-size: 11px;
  color: #b9ccd3;
}

.sn-search {
  height: 38px;
  background: rgba(255,255,255,.12);
  border-radius: 5px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 10px;
  margin-bottom: 15px;
}

.sn-search input {
  width: 100%;
  border: 0;
  outline: 0;
  background: transparent;
  color: #ffffff;
}

.sn-search input::placeholder {
  color: #c9d7dc;
}

.sn-nav {
  flex: 1;
}

.sn-nav-item {
  display: flex;
  align-items: center;
  gap: 11px;
  min-height: 42px;
  padding: 0 12px;
  margin: 2px 0;
  color: #e7f0f3 !important;
  text-decoration: none !important;
  border-radius: 5px;
  font-size: 13px;
}

.sn-nav-item.active {
  background: #164a5b;
  box-shadow: inset 3px 0 0 #81d742;
  font-weight: 600;
}

.sn-nav-item:hover,
.sn-sub-item:hover {
  background: rgba(255,255,255,.10);
  color: #ffffff !important;
}

.sn-nav-icon {
  width: 20px;
  text-align: center;
}

.sn-section {
  margin: 5px 0 8px;
}

.sn-section-title {
  display: flex;
  justify-content: space-between;
  color: #b8cbd2;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  padding: 10px 12px 6px;
}

.sn-sub-item {
  display: flex;
  align-items: center;
  color: #e6eef1 !important;
  text-decoration: none !important;
  font-size: 13px;
  padding: 9px 12px 9px 43px;
  border-radius: 5px;
}

.sn-count {
  margin-left: auto;
  min-width: 21px;
  height: 21px;
  border-radius: 11px;
  background: #81d742;
  color: #062f3d;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 700;
}

/* TOP */

.topbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 28px;
}

.topbar h1 {
  margin: 0 0 6px;
  font-size: 27px;
  font-weight: 700;
}

.topbar p {
  margin: 0;
  color: #7b849d;
}

.top-actions {
  display: flex;
  align-items: center;
  gap: 18px;
}

.search-box {
  border: 1px solid #e0e5ed;
  background: #ffffff;
  border-radius: 10px;
  padding: 10px 14px;
  width: 300px;
}

.search-box input {
  border: none;
  outline: none;
  width: 250px;
}

.profile-box {
  display: flex;
  align-items: center;
  gap: 10px;
}

.profile-box small {
  display: block;
  color: #7b849d;
}

.avatar {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  background: #eef2ff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
}

/* CARDS */

.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
  margin-bottom: 22px;
}

.stat-card {
  background: #ffffff;
  padding: 22px;
  border-radius: 14px;
  border: 1px solid #e7eaf0;
  min-height: 190px;
}

.stat-icon {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
  margin-bottom: 15px;
}

.stat-icon.green {
  background: #e5f7f1;
}

.stat-icon.blue {
  background: #e9f0ff;
}

.stat-icon.purple {
  background: #f0eaff;
}

.stat-icon.orange {
  background: #fff0e4;
}

.stat-title {
  font-size: 15px;
  font-weight: 700;
  margin-bottom: 10px;
}

.stat-value {
  font-size: 32px;
  font-weight: 700;
  margin-bottom: 20px;
}

.stat-value span {
  font-size: 13px;
  font-weight: 400;
  margin-left: 4px;
}

.stat-card a {
  color: #1769e0;
  text-decoration: none;
  font-size: 13px;
}

/* LOWER */

.content-grid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 20px;
}

.panel {
  background: #ffffff;
  border: 1px solid #e7eaf0;
  border-radius: 14px;
  padding: 18px;
}

.panel-header h3 {
  margin-top: 0;
}

table {
  width: 100%;
  border-collapse: collapse;
}

th,
td {
  padding: 12px 10px;
  border-bottom: 1px solid #edf0f4;
  text-align: left;
  font-size: 13px;
}

th {
  background: #f8f9fb;
}

.empty-row {
  text-align: center;
  color: #8b93a8;
}

.status-pill {
  display: inline-block;
  padding: 5px 10px;
  border-radius: 14px;
  font-size: 11px;
}

.status-approved {
  background: #e5f7ef;
  color: #14875b;
}

.status-rejected {
  background: #fde9e8;
  color: #d33b32;
}

.status-pending {
  background: #fff3dc;
  color: #d88400;
}

.quick-actions {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
}

.quick-actions a {
  border: 1px solid #e6e9ef;
  border-radius: 10px;
  min-height: 110px;
  text-align: center;
  text-decoration: none;
  color: #101d48;
  padding: 16px 8px;
}

.quick-icon {
  font-size: 28px;
  margin-bottom: 10px;
}

.analytics-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 18px;
  margin-top: 20px;
  margin-bottom: 20px;
}

.analytics-card {
  background: #ffffff;
  border: 1px solid #e4e8ef;
  border-radius: 14px;
  padding: 22px;
  box-shadow: 0 3px 10px rgba(0,0,0,.04);
}

.analytics-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 18px;
}

.analytics-header h3 {
  margin: 0;
  font-size: 18px;
  color: #0f1b45;
}

.analytics-header p {
  margin: 4px 0 0;
  color: #7b8497;
  font-size: 12px;
}

.analytics-body {
  display: flex;
  align-items: center;
  gap: 16px;
}

.donut-wrap {
  flex: 0 0 135px;
  display: flex;
  justify-content: center;
}

.donut-chart {
  width: 135px;
  height: 135px;
  border-radius: 50%;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

.donut-chart::after {
  content: "";
  width: 82px;
  height: 82px;
  background: #ffffff;
  border-radius: 50%;
  position: absolute;
}

.donut-center {
  position: relative;
  z-index: 2;
  text-align: center;
}

.donut-center span {
  display: block;
  color: #7b8497;
  font-size: 12px;
}

.donut-center strong {
  display: block;
  font-size: 22px;
  margin-top: 2px;
  color: #0f1b45;
}

.bell {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  text-decoration: none;
  color: #0f1b45;
  cursor: pointer;
}

.bell .sn-count {
  position: absolute;
  top: -3px;
  right: -4px;
}

.legend-list {
  flex: 1;
}

.legend-row {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 6px 0;
  border-bottom: 1px solid #f0f2f5;
}

.legend-row:last-child {
  border-bottom: none;
}

.legend-label {
  flex: 1;
  color: #25304e;
  font-size: 12px;
}

.legend-row strong {
  color: #0f1b45;
}

.legend-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  display: inline-block;
}

.approved-dot {
  background: #34c38f;
}

.pending-hod-dot {
  background: #f59e0b;
}

.pending-hr-dot {
  background: #3b82f6;
}

.rejected-dot {
  background: #ef4444;
}

.cancelled-dot {
  background: #8b5cf6;
}

.case-open-dot {
  background: #f59e0b;
}

.case-progress-dot {
  background: #3b82f6;
}

.case-resolved-dot {
  background: #34c38f;
}

.case-closed-dot {
  background: #6b7280;
}


.view-calendar {
  color: #1769e0;
  text-decoration: none;
  font-size: 12px;
  white-space: nowrap;
}

.upcoming-list {
  width: 100%;
}

.upcoming-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 0;
  border-bottom: 1px solid #edf0f4;
}

.upcoming-item:last-child {
  border-bottom: none;
}

.employee-avatar {
  width: 34px;
  height: 34px;
  min-width: 34px;
  border-radius: 50%;
  background: #e9f0ff;
  color: #1769e0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 12px;
}

.upcoming-info {
  min-width: 0;
}

.employee-name {
  font-size: 13px;
  font-weight: 700;
  color: #0f1b45;
  margin-bottom: 3px;
}

.leave-dates {
  font-size: 11px;
  color: #4b5563;
  margin-bottom: 2px;
}

.leave-type {
  font-size: 11px;
  color: #7b8497;
}

.no-upcoming {
  min-height: 135px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  color: #7b8497;
}

.no-upcoming-icon {
  font-size: 26px;
  margin-bottom: 8px;
}

.no-upcoming strong {
  color: #25304e;
  margin-bottom: 4px;
}

.no-upcoming span {
  font-size: 11px;
}

@media (max-width: 1200px) {

  .analytics-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .upcoming-card {
    grid-column: 1 / -1;
  }
}

@media (max-width: 768px) {

  .analytics-grid {
    grid-template-columns: 1fr;
  }

  .upcoming-card {
    grid-column: auto;
  }

  .analytics-body {
    flex-direction: column;
  }

  .legend-list {
    width: 100%;
  }
}

@media (max-width: 1100px) {
  .stats-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .content-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 768px) {
  .sn-sidebar {
    display: none;
  }

  .stats-grid {
    grid-template-columns: 1fr;
  }

  .topbar {
    display: block;
  }

  .top-actions {
    margin-top: 18px;
  }
}

sp_widget.script:
(function() {

    data.userName = gs.getUserDisplayName();

    var initials = "";
    var parts = data.userName.split(" ");

    for (var i = 0; i < parts.length && i < 2; i++) {
        if (parts[i])
            initials += parts[i].charAt(0).toUpperCase();
    }

    data.initials = initials;

    data.standardDepartmentId = "";
    data.customDepartmentId = "";
    data.departmentName = "";
    data.departmentCode = "";

    data.teamCount = 0;
    data.pendingCount = 0;
    data.approvedThisMonth = 0;
    data.openHrCases = 0;
    data.recentLeaves = [];



    // ----------------------------------
    // 1. GET LOGGED-IN USER DEPARTMENT
    // cmn_department
    // ----------------------------------

    var userGR = new GlideRecord('sys_user');

    if (userGR.get(gs.getUserID())) {

        data.standardDepartmentId =
            userGR.getValue('department') || "";

        data.departmentName =
            userGR.getDisplayValue('department') || "";
    }

    if (!data.standardDepartmentId)
        return;


    // ----------------------------------
    // 2. GET DEPARTMENT CODE
    // Example: CSE
    // ----------------------------------

    var stdDeptGR = new GlideRecord('cmn_department');

    if (stdDeptGR.get(data.standardDepartmentId)) {

        data.departmentCode =
            stdDeptGR.getValue('id') || "";
    }


    // ----------------------------------
    // 3. FIND CUSTOM DEPARTMENT
    // x_snc_unified_hr_0_department
    // ----------------------------------

    if (data.departmentCode) {

        var customDeptGR =
            new GlideRecord('x_snc_unified_hr_0_department');

        customDeptGR.addQuery(
            'department_code',
            data.departmentCode
        );

        customDeptGR.setLimit(1);
        customDeptGR.query();

        if (customDeptGR.next()) {

            data.customDepartmentId =
                customDeptGR.getUniqueValue();
        }
    }


    // ----------------------------------
	// 4. TEAM COUNT
	// Exclude logged-in HOD
	// ----------------------------------

	var teamGA =
		new GlideAggregate(
			'sys_user'
		);

	teamGA.addQuery(
		'department',
		data.standardDepartmentId
	);

	teamGA.addQuery(
		'active',
		true
	);

	// Exclude logged-in HOD
	teamGA.addQuery(
		'sys_id',
		'!=',
		gs.getUserID()
	);

	teamGA.addAggregate(
		'COUNT'
	);

	teamGA.query();

	if (teamGA.next()) {

		data.teamCount =
			parseInt(
				teamGA.getAggregate(
					'COUNT'
				),
				10
			) || 0;
	}


    // If custom department was not found,
    // we cannot query application records.
    if (!data.customDepartmentId)
        return;


    // ----------------------------------
    // 5. PENDING HOD LEAVE REQUESTS
    // Uses custom Department
    // ----------------------------------

    var pendingGA =
        new GlideAggregate(
            'x_snc_unified_hr_0_leave_request'
        );

    pendingGA.addQuery(
        'department',
        data.customDepartmentId
    );

    pendingGA.addQuery(
        'status',
        'pending_hod'
    );

    pendingGA.addAggregate('COUNT');
    pendingGA.query();

    if (pendingGA.next()) {

        data.pendingCount =
            parseInt(
                pendingGA.getAggregate('COUNT'),
                10
            ) || 0;
    }


    // ----------------------------------
// 6. APPROVED THIS MONTH
// ----------------------------------

var nowGdt = new GlideDateTime();

var year = nowGdt.getYearUTC();
var month = nowGdt.getMonthUTC();

var monthString =
    month < 10 ? "0" + month : "" + month;

var startMonth = new GlideDateTime(
    year + "-" + monthString + "-01 00:00:00"
);

// Calculate first day of next month
var nextMonth = month + 1;
var nextYear = year;

if (nextMonth > 12) {
    nextMonth = 1;
    nextYear = year + 1;
}

var nextMonthString =
    nextMonth < 10 ? "0" + nextMonth : "" + nextMonth;

var startNextMonth = new GlideDateTime(
    nextYear +
    "-" +
    nextMonthString +
    "-01 00:00:00"
);

var approvedGA =
    new GlideAggregate(
        'x_snc_unified_hr_0_leave_request'
    );

approvedGA.addQuery(
    'department',
    data.customDepartmentId
);

approvedGA.addQuery(
    'status',
    'approved'
);

approvedGA.addQuery(
    'applied_on',
    '>=',
    startMonth
);

approvedGA.addQuery(
    'applied_on',
    '<',
    startNextMonth
);

approvedGA.addAggregate('COUNT');
approvedGA.query();

if (approvedGA.next()) {

    data.approvedThisMonth =
        parseInt(
            approvedGA.getAggregate('COUNT'),
            10
        ) || 0;
}

    // ----------------------------------
// 7. OPEN HR CASES
// HR Case -> Request By -> Department
// ----------------------------------

var caseGA = new GlideAggregate(
    'x_snc_unified_hr_0_hr_case'
);

// Only cases raised by users in HOD's department
caseGA.addQuery(
    'request_by.department',
    data.standardDepartmentId
);

//Exclude the HOD
caseGA.addQuery(
    'request_by',
    '!=',
    gs.getUserID()
);

// Exclude resolved/closed cases
caseGA.addQuery(
    'status',
    'NOT IN',
    'resolved,closed'
);

caseGA.addAggregate('COUNT');
caseGA.query();

if (caseGA.next()) {
    data.openHrCases =
        parseInt(
            caseGA.getAggregate('COUNT'),
            10
        ) || 0;
}

    // ----------------------------------
    // 8. RECENT LEAVE REQUESTS
    // ----------------------------------

    var recentGR =
        new GlideRecord(
            'x_snc_unified_hr_0_leave_request'
        );

    recentGR.addQuery(
        'department',
        data.customDepartmentId
    );

    recentGR.orderByDesc('applied_on');
    recentGR.setLimit(5);
    recentGR.query();

    while (recentGR.next()) {

        data.recentLeaves.push({

            number:
                recentGR.getDisplayValue('number'),

            employee:
                recentGR.getDisplayValue('requested_by'),

            leave_type:
                recentGR.getDisplayValue('leave_type'),

            start_date:
                recentGR.getDisplayValue('start_date'),

            end_date:
                recentGR.getDisplayValue('end_date'),

            status:
                recentGR.getDisplayValue('status')
        });
    }

	data.leaveAnalytics = {
		pendingHod: 0,
		pendingHr: 0,
		approved: 0,
		rejected: 0,
		cancelled: 0,
		total: 0
	};

	data.hrCaseAnalytics = {
		open: 0,
		inProgress: 0,
		resolved: 0,
		closed: 0,
		total: 0
	};

	// ----------------------------------
	// 9. LEAVE REQUESTS BY STATUS
	// ----------------------------------

	var leaveStatusGA =
		new GlideAggregate(
			'x_snc_unified_hr_0_leave_request'
		);

	leaveStatusGA.addQuery(
		'department',
		data.customDepartmentId
	);

	leaveStatusGA.addAggregate('COUNT');
	leaveStatusGA.groupBy('status');
	leaveStatusGA.query();

	while (leaveStatusGA.next()) {

		var leaveStatus =
			leaveStatusGA.getValue('status');

		var leaveCount =
			parseInt(
				leaveStatusGA.getAggregate('COUNT'),
				10
			) || 0;

		data.leaveAnalytics.total += leaveCount;

		if (leaveStatus == 'pending_hod') {
			data.leaveAnalytics.pendingHod = leaveCount;
		}
		else if (leaveStatus == 'pending_hr') {
			data.leaveAnalytics.pendingHr = leaveCount;
		}
		else if (leaveStatus == 'approved') {
			data.leaveAnalytics.approved = leaveCount;
		}
		else if (leaveStatus == 'rejected') {
			data.leaveAnalytics.rejected = leaveCount;
		}
		else if (leaveStatus == 'cancelled') {
			data.leaveAnalytics.cancelled = leaveCount;
		}
	}

	// ----------------------------------
	// 10. HR CASES BY STATUS
	// HR Case -> Request By -> Department
	// ----------------------------------

	var hrStatusGA =
		new GlideAggregate(
			'x_snc_unified_hr_0_hr_case'
		);

	hrStatusGA.addQuery(
		'request_by.department',
		data.standardDepartmentId
	);

	hrStatusGA.addQuery(
		'request_by',
		'!=',
		gs.getUserID()
	);

	hrStatusGA.addAggregate('COUNT');
	hrStatusGA.groupBy('status');
	hrStatusGA.query();

	while (hrStatusGA.next()) {

		var hrStatus =
			hrStatusGA.getValue('status');

		var hrCount =
			parseInt(
				hrStatusGA.getAggregate('COUNT'),
				10
			) || 0;

		data.hrCaseAnalytics.total += hrCount;

		if (hrStatus == 'open') {
			data.hrCaseAnalytics.open = hrCount;
		}
		else if (hrStatus == 'in_progress') {
			data.hrCaseAnalytics.inProgress = hrCount;
		}
		else if (hrStatus == 'resolved') {
			data.hrCaseAnalytics.resolved = hrCount;
		}
		else if (hrStatus == 'closed') {
			data.hrCaseAnalytics.closed = hrCount;
		}
	}

	// ==============================
// Notification Count
// ==============================

data.notificationCount = 0;

var notificationGR = new GlideAggregate('ui_notification_inbox');

notificationGR.addQuery('recipient', gs.getUserID());
notificationGR.addQuery('status', 'new');
notificationGR.addAggregate('COUNT');

notificationGR.query();

if (notificationGR.next()) {
    data.notificationCount = parseInt(
        notificationGR.getAggregate('COUNT'),
        10
    ) || 0;
}

})();
